CREATE TABLE papers (id TEXT PRIMARY KEY, title TEXT NOT NULL, authors TEXT NOT NULL, source TEXT NOT NULL, date TEXT NOT NULL, tags TEXT NOT NULL, summary TEXT NOT NULL, abstract TEXT NOT NULL, url TEXT NOT NULL);
CREATE TABLE bookmarks (user_id TEXT NOT NULL, paper_id TEXT NOT NULL REFERENCES papers(id), created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, PRIMARY KEY(user_id,paper_id));
INSERT INTO papers VALUES ('arXiv:1706.03762','Attention Is All You Need','Vaswani et al.','arXiv','Jun 2017','["Transformers","Attention"]','Introduces the Transformer architecture, replacing recurrent sequence processing with attention.','Editorial reading note: This work introduces an attention-based encoder-decoder architecture and evaluates it on machine translation. Consult the original paper for methods, benchmarks, and limitations.','https://arxiv.org/abs/1706.03762');
INSERT INTO papers VALUES ('arXiv:2501.12948','DeepSeek-R1: Incentivizing Reasoning Capability in LLMs via Reinforcement Learning','DeepSeek-AI','arXiv','Jan 2025','["Reasoning","RL"]','Explores reinforcement learning for reasoning and distillation into smaller models.','Editorial reading note: The authors investigate reinforcement learning for reasoning, with R1-Zero and a cold-start R1 training pipeline. Read the source for evaluation conditions and limitations.','https://arxiv.org/abs/2501.12948');
